// The course's view of the Tech Spanish glossary.
// glossary.json is generated by content/tech-spanish/build.mjs (don't edit it
// here); these helpers turn its terms into tables, examples and flashcards so
// lessons never retype a translation by hand.
import data from './glossary.json';
import { both } from '../../engine/i18n';

const BY_ID = new Map(data.terms.map((t) => [t.id, t]));

export const GROUPS = data.groups;
export const SOURCES = data.sources;
export const TERMS = data.terms;

/** One glossary term by id. Throws on a typo, so a broken lesson fails the tests. */
export const term = (id) => {
  const t = BY_ID.get(id);
  if (!t) throw new Error(`Unknown glossary term "${id}" (see content/tech-spanish/glossary.source.mjs)`);
  return t;
};

const cell = (s) => String(s ?? '—').replace(/\|/g, '\\|').replace(/\n/g, ' ');

/** A Markdown table of terms: English, Spanish, and the three registers. */
export const termTable = (ids) => {
  const rows = ids.map(term);
  const table = (head) => [
    `| ${head.join(' | ')} |`,
    `|${head.map(() => '---').join('|')}|`,
    ...rows.map((t) => `| **${cell(t.en)}** | ${cell(t.register.formal)} | ${cell(t.register.casual)} | ${cell(t.register.slang)} |`),
  ].join('\n');
  return both(
    table(['English', 'Formal Spanish', 'With the team', 'Slang']),
    table(['English', 'Español formal', 'Con el equipo', 'Jerga']),
  );
};

/** Each term's example sentence in both languages, as a Markdown list. */
export const examples = (ids) => {
  const list = (label) => ids.map(term).map((t) => `- **${t.en}** · ${label}\n  - EN: ${t.example.en}\n  - ES: ${t.example.es}`).join('\n');
  return both(list('example'), list('ejemplo'));
};

/** Warnings for the false friends and regional differences among these terms (empty string if none). */
export const traps = (ids) => {
  const rows = ids.map(term).filter((t) => t.falseFriend || t.region);
  if (!rows.length) return '';
  const list = (ff, rg) => rows.map((t) => [
    t.falseFriend && `- ⚠️ **${t.en}** (${ff}): ${t.falseFriend}`,
    t.region && `- 🌎 **${t.en}** (${rg}): ${t.region}`,
  ].filter(Boolean).join('\n')).join('\n');
  return both(list('false friend', 'Spain / Latin America'), list('falso amigo', 'España / Latinoamérica'));
};

/**
 * Flashcards for these terms in the Study Hub card shape, both directions by
 * default: English → Spanish ("-en-es") and Spanish → English ("-es-en").
 */
export const cardsFor = (ids, { directions = ['en-es', 'es-en'] } = {}) => ids.flatMap((id) => {
  const t = term(id);
  const warn = t.falseFriend ? `\n\n⚠️ ${t.falseFriend}` : '';
  return directions.map((dir) => (dir === 'en-es'
    ? {
      id: `${id}-en-es`,
      front: `**${t.en}**`,
      back: both(
        `**${t.es}**\n\nAt work: ${t.atWork}\n\n*${t.example.es}*${warn}`,
        `**${t.es}**\n\nEn el trabajo: ${t.atWork}\n\n*${t.example.es}*${warn}`,
      ),
      hint: t.example.en,
      tags: [t.group, 'en-es'],
      difficulty: t.difficulty,
    }
    : {
      id: `${id}-es-en`,
      front: `**${t.es.split(';')[0].trim()}**`,
      back: `**${t.en}**\n\n*${t.example.en}*`,
      hint: t.example.es,
      tags: [t.group, 'es-en'],
      difficulty: t.difficulty,
    }));
});
